  // Pairings shown in the discovery feed = programs that are published.
  // A "promoted" flag marks team-elevated high performers.
  function pairings() {
    return programs.filter(p => p.published).map(p => ({
      id: p.id,
      name: p.name,
      author: p.author,
      tier: p.tier,
      service: p.service,
      tracks: p.workouts.length,
      duration: p.duration,
      upvotes: p.upvotes,
      promoted: p.upvotes >= 300,
      cover: p.name[0]
    }));
  }
  function song(id) {
    return songs.find(s => s.id === id);
  }
  function program(id) {
    return programs.find(p => p.id === id);
  }

  // ── Workout structure helpers (parsed from `detail`) ─────────────
  // Used by the now-playing-as-timer (sets/rest) and cadence matching.
  function setsFor(w) {
    if (!w) return 4;
    if (typeof w.sets === "number") return w.sets;
    const m = /^(\d+)\s*[×x]/.exec(w.detail || "");
    if (m) return Math.max(1, parseInt(m[1], 10));
    if (/min|mobility|cool/i.test(w.detail || w.name || "")) return 1; // time block
    return 3;
  }
  function restFor(w) {
    // seconds of rest between sets
    const z = zoneFor(w);
    return z >= 5 ? 30 : z >= 4 ? 45 : 60;
  }
  function zoneFor(w) {
    // 1–5 intensity (drives energy arc)
    if (!w) return 3;
    if (typeof w.zone === "number") return w.zone;
    const d = (w.detail || "") + " " + (w.name || "");
    const zm = /zone\s*(\d)/i.exec(d);
    if (zm) return parseInt(zm[1], 10);
    if (/cool|mobility|drift/i.test(d)) return 1;
    if (/run|row|ski|wall|burpee|carry|sled/i.test(d)) return 5;
    const rm = /^(\d+)\s*[×x]\s*(\d+)/.exec(w.detail || "");
    if (rm) {
      const reps = parseInt(rm[2], 10);
      return reps <= 5 ? 4 : reps <= 10 ? 3 : 4;
    }
    return 3;
  }
  function targetBpmFor(w) {
    // ideal cadence BPM for the move
    if (w && typeof w.cad === "number") return w.cad;
    return [0, 84, 104, 122, 140, 156][zoneFor(w)] || 124;
  }
  // Cadence fit between a song and a move's target BPM (also matches the
  // half/double-time feel, the way a real runner locks to a beat).
  function cadenceFit(bpm, target) {
    if (!bpm || !target) return {
      pct: 0,
      label: "—",
      delta: 0,
      lock: false
    };
    const cands = [bpm, bpm / 2, bpm * 2];
    let best = Infinity,
      used = bpm;
    cands.forEach(c => {
      const d = Math.abs(c - target);
      if (d < best) {
        best = d;
        used = c;
      }
    });
    const pct = Math.max(0, Math.round(100 - best / target * 100 * 1.6));
    const label = pct >= 88 ? "Locked" : pct >= 68 ? "Close" : "Off-tempo";
    return {
      pct,
      label,
      delta: Math.round(used - target),
      lock: pct >= 88,
      halftime: used !== bpm
    };
  }

