  // Which species a finished move summons: matches the move's zone, rarer
  // tiers for harder zones. Returns the candidate (caller checks if earned).
  function speciesForWorkout(w) {
    const z = zoneFor(w);
    const pool = species.filter(s => s.zone === z);
    if (!pool.length) return species[0];
    // deterministic pick by workout id so it's stable
    const seed = (w.id || "x").split("").reduce((a, c) => a + c.charCodeAt(0), 0);
    return pool[seed % pool.length];
  }

