  // ── RLS: the single scoping gate. Returns rows the session may see ─
  // entity ∈ classes|members|tx|events. Demonstrates row-level security:
  // the SAME query returns different rows per identity.
  function scope(entity, rows, session) {
    if (!session) return [];
    if (session.role === "admin") return rows; // global read
    switch (entity) {
      case "classes":
        if (session.role === "host") return rows.filter(r => r.floorId === session.floorId);
        if (session.role === "coach") return rows.filter(r => r.coachId === session.userId);
        return rows;
      // members browse all bookable
      case "members":
        if (session.role === "host") return rows.filter(r => r.floorId === session.floorId);
        if (session.role === "coach") return rows.filter(r => r.coachId === session.userId);
        if (session.role === "member") return rows.filter(r => r.id === session.userId); // self only
        return rows;
      case "tx":
        if (session.role === "host") return rows.filter(r => r.floorId === session.floorId);
        if (session.role === "coach") return rows.filter(r => r.who === session.name);
        if (session.role === "member") return rows.filter(r => r.who === session.name);
        return rows;
      case "events":
        return rows;
      // discovery is public
      default:
        return rows;
    }
  }
