      // { programId, workoutId, playing, progress }
      savedPairings: [],
      // program ids saved by the member
      raidJoined: null,
      // raid id the member is locked into
      // ── gamification world ──
      earnedSpecies: ["sp_reefox", "sp_dunehare", "sp_saltgull", "sp_ironstag"],
      // dex
      pendingCapture: null,
      // species id mid-capture (overlay)
      questProgress: {},
      // { questId: n }
      questClaimed: [],
