  // Per-class gate computed against the member's plan + usage.
  // kind ∈ included | credit | dropin | locked
  function gateFor(klass, ent) {
    ent = ent || entitlement;
    const p = plan_(ent.planId) || plans[0];
    if (klass && klass.tierLock && klass.tierLock !== p.name) return {
      kind: "locked",
      label: "Upgrade",
      price: null
    };
    if (klass && klass.dropInOnly) return {
      kind: "dropin",
      label: "Drop-in",
      price: klass.price || 28
    };
    if (ent.usage.classes >= p.classesPerMonth) return {
      kind: "credit",
      label: "Use 1 credit",
      price: null
    };
    return {
      kind: "included",
      label: "Included",
      price: null
    };
  }

