  function genSession(opts) {
    opts = opts || {};
    const warm = exercises.filter(e => e.block === "warmup").slice(0, 1);
    const main = exercises.filter(e => e.block === "main");
    const fin = exercises.filter(e => e.block === "finisher").slice(0, 1);
    const moves = warm.concat(main, fin);
    return {
      title: "Pier 9 · Pull",
      minutes: opts.minutes || 45,
      blocks: ["warmup", "main", "finisher"],
      moves,
      stats: {
        moves: moves.length,
        volume: 1840,
        blocks: 3
      }
    };
  }

